/// <summary>
/// AVA/WEN/2024/09/27
/// </summary>
/// <param name = "_dataContract">AVASetDlvResponsibleContract</param>
public void runService(AVASetDlvResponsibleContract _dataContract)
{
    Set recordSet;
    SetEnumerator se;
    SalesTable salesTable;
    HcmWorkerRecId worker = _dataContract.parmWorker();


    if (worker && conLen(_dataContract.parmRecordCon()) > 0)
    {
        recordSet = Set::create(_dataContract.parmRecordCon());
        se = recordSet.getEnumerator();
        while (se.moveNext())
        {
            salesTable = se.current();
            this.setDlvResponsible(salesTable, worker);
        }
    }
}

private void setDlvResponsible(SalesTable _salesTable, HcmWorkerRecId _worker)
{
    if(_salesTable)
    {
        ttsbegin;
        _salesTable.selectForUpdate(true);
        _salesTable.AVADlvResponsible = _worker;
        _salesTable.update();
        ttscommit;
    }

}
